export const meta = {
  name: 'entity-registry',
  description: 'Synthesize the canonical token registry (ids + exact KSA values + mapping guidance) from the inventory',
  phases: [{ title: 'Synthesize', detail: '3 agents, one per category partition' }, { title: 'Check', detail: 'verify surface forms against the v5 dictionary' }],
}
const B = '/home/user/uptal-workroom/prototypes/build'
const COMMON = `Context: ${B}/DESIGN.md (read it: token grammar, scopes, the {@id|literal} escape hatch). The v5 dictionary (final runtime values) is ${B}/data/v5-dump.json (keys en, ar) — grep it to confirm exact surface forms. The raw inventory from 11 scanners is ${B}/data/inventory.json (entities[] with id/category/en/ar/archetype/sample_keys, plus code_notes[]); it has duplicates and inconsistent ids.
Goal: produce the CANONICAL registry of token ids for your partition. Tokenizers will replace each KSA literal in v5 copy with {@id}; market packs will give each id a value per market. So for each id give:
  "id": {"cat": category, "en": exact KSA English surface form as written in v5, "ar": exact KSA Gulf-Arabic surface form as written in v5 (base form, WITHOUT attached prefixes like و/ب/ل/ال when those are grammatical; include ال only when it is part of the name e.g. الرياض), "arn": neutral formal Arabic form (usually = ar for names), "fr": French form (e.g. Riyad, La Mecque, Arabie saoudite), "scope": "target"|"residence"|"persona", "archetype": what it is, "map": one-line instruction for picking the equivalent in another market (e.g. "market's #1 finance city", "largest national oil/energy employer, else largest industrial", "a female recruiter's full name typical locally", "the local data-protection law's short name"), "count": approx occurrences, "keys": up to 8 dictionary keys}
Rules: one id per real thing; separate ids for different surface variants that are not just grammatical prefixes (e.g. ctry.n "Saudi Arabia", ctry.s "Saudi", ctry.dem "Saudi" adjective, ctry.k "the Kingdom", ctry.ksa "KSA"); keep ids short, lowercase, dot-namespaced: p.* persona, ctry.* country forms, reg.* region (GCC/the Gulf), city.*, co.*, ppl.* (contacts/recruiters), adv.* (Uptal advisors/staff), cert.*, uni.*, gov.*, prog.* (nationalisation), pay.*, tax.*, cur.*, legal.*, cal.* (work week, holidays, deadlines), lang.* (language norms), phone.*, misc.* (other market phrases). Ids starting pay./tax./cur./phone./legal./res. are RESIDENCE scope; p.* PERSONA; all else TARGET. Prices and salary amounts are NOT registry ids (they become {@$:N} / {@sal:N} tokens) — but list in "notes" any amount that is neither a product price nor a monthly salary (e.g. an annual figure, a market statistic) with a suggested treatment.
Write your output as JSON to the file named below: {"entities": {id: {...}}, "notes": [..]}. Validate with python3 -I -c "import json;json.load(open(PATH))". Return a short summary (counts per namespace, tricky cases).`
const PARTS = [
  { k: 'A', file: `${B}/markets/registry-A.json`, what: 'ALL employers / companies / organisations (co.*), including employer-type phrases like "giga-projects", stock exchange, sovereign fund, current/fictional employers (Acme Financial / Acme Capital → p.employer / p.employer2 belong to partition C, skip them).' },
  { k: 'B', file: `${B}/markets/registry-B.json`, what: 'country name forms (ctry.*), region forms (reg.*), cities and districts (city.*), people names: recruiters/contacts/hiring managers/testimonial authors (ppl.*), Uptal advisors/coaches/staff (adv.* — include each advisor first/last/full/initials/title if used separately), certifications (cert.*), universities (uni.*), government platforms (gov.*), nationalisation programmes (prog.*), phone formats (phone.*), time zones.' },
  { k: 'C', file: `${B}/markets/registry-C.json`, what: 'the persona Noura Al-Amri (p.*: first, last, full, initials, email, phone, city, title, years, employer, employer2, degree, uni, cert, nationality forms, bio sentences that are market-specific, CV file name, team size, target-cities phrase...), payment brands and methods (pay.*: mada, Apple Pay, Tabby, Tamara, STC Pay, Visa/Mastercard lines...), tax (tax.*: VAT 15%, VAT included phrases), currency words (cur.*: riyal, SAR when written as a word not as an amount), legal/regulatory (legal.*: PDPL, SDAIA, labour law, e-commerce law...), calendar/culture (cal.*: Sunday-Thursday week, Thursday deadline, Ramadan, Eid, National Day...), language norms (lang.*: Arabic required, bilingual CV...), and misc market phrases (misc.*). Also the salary-period phrases ("a month", "بالشهر") — prefer the built-in {@per}/{@perw}/{@pers} tokens; register misc.* ids only for phrasings those can not express.' },
]
phase('Synthesize')
const out = await parallel(PARTS.map(p => () => agent(`${COMMON}\n\nYOUR PARTITION (${p.k}): ${p.what}\nOutput file: ${p.file}`, { label: `registry-${p.k}`, phase: 'Synthesize' })))
phase('Check')
const check = await agent(`${COMMON}\n\nThree partition files were written: ${PARTS.map(p => p.file).join(', ')}. Summaries:\n${out.filter(Boolean).join('\n---\n')}\n\nYou are the CHECKER. Merge them into ${B}/markets/registry.json as {"entities": {...all ids...}, "notes": [...]} with no duplicate ids (resolve collisions; keep the namespace rules). For every entity verify its "en" and "ar" literally occur in ${B}/data/v5-dump.json (en values / ar values) at least once (allowing Arabic grammatical prefixes); fix or drop phantom ones. Make sure p.first/p.last/p.full/p.initials/p.email/p.city/p.title/p.employer/p.employer2 exist. Write a quick coverage report: for each KSA term in this list, which id covers it: Riyadh, Jeddah, Dammam, Al Khobar, Dhahran, Mecca, Medina, Abha, Tabuk, Saudi Arabia, Saudi, KSA, the Kingdom, GCC, the Gulf, Aramco, SABIC, NEOM, stc, Jahez, Rewaa, Al Rajhi, Alinma, SNB, Riyad Bank, Maaden, Almarai, Mobily, Tadawul, PIF, Qiddiya, Bupa Arabia, Tabby, Tamara, SOCPA, King Saud University, Iqama, Qiwa, GOSI, Absher, Saudization, mada, STC Pay, Noura, Al-Amri, +966, VAT 15%, PDPL. Return the report.`, { label: 'registry-merge', phase: 'Check' })
return { parts: out, check }
